import XCTest
@testable import ReverbQSO

final class SpeexCodecTests: XCTestCase {
    // Four quality-8 narrowband frames generated by official Speex 1.2.1
    // from 640 samples of a 10,000-amplitude sine wave (phase step 0.1728).
    static let fixture = Data(hex: "")

    func testSpeechPacketDecodesTo640Samples() throws {
        let samples = try XCTUnwrap(SpeexCodec().decodePacket(Self.fixture))
        XCTAssertEqual(samples.count, 640)
        XCTAssertGreaterThan(samples.reduce(0) { $0 + abs(Int($1)) }, 10_000)
    }

    func testMalformedPacketDoesNotLeakPartialSamplesOrState() throws {
        let codec = SpeexCodec()
        let original = try XCTUnwrap(codec.decodePacket(Self.fixture))
        XCTAssertNil(codec.decodePacket(Data(Self.fixture.prefix(Self.fixture.count / 2))))
        XCTAssertEqual(codec.decodePacket(Self.fixture), original)
        XCTAssertNil(codec.decodePacket(Data()))
        XCTAssertNil(codec.decodePacket(Data(repeating: 0, count: 513)))
    }

    func testResetStartsIndependentSession() throws {
        let codec = SpeexCodec()
        let original = try XCTUnwrap(codec.decodePacket(Self.fixture))
        _ = codec.decodePacket(Self.fixture)
        codec.reset()
        XCTAssertEqual(codec.decodePacket(Self.fixture), original)
    }
}

private extension Data {
    init(hex: String) {
        self.init()
        var position = hex.startIndex
        while position < hex.endIndex {
            let end = hex.index(position, offsetBy: 2)
            append(UInt8(hex[position..<end], radix: 16)!)
            position = end
        }
    }
}
